@startuml

class Bookmaker {
  + name : string
  + AcceptBets(bet: Bet) : void
  + CalculateWinnings() : double
}

class Bettor {
  + id : int
  + name : string
  + PlaceBet(bet: Bet) : void
}

class Race {
  + id : int
  + runners : Runner[]
  + winner : Runner
}

class Runner {
  + id : int
  + horseName : string
  + jockey : Jockey
}

class Jockey {
  + id : int
  + name : string
}

class Bet {
  + id : int
  + bettor : Bettor
  + race : Race
  + runner : Runner
  + amount : double
  + odds : double
}

Bookmaker "1" -- "*" Bettor : manages
Bettor "0..*" -- "1..*" Bet : places
Race "1" -- "*" Runner : has
Runner "0..1" -- "1" Jockey : riddenBy
Bet "1" -- "1" Race : refersTo
Bet "1" -- "1" Runner : on

@enduml

